'use client';

import { useCallback } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { conversationOf, CONVERSATIONS, WRITER } from './data';
import { InboxList } from './inbox-list';
import { ReadingPane } from './reading-pane';
import {
  handledCountOf,
  INITIAL,
  LOOP_AFTER_MS,
  nextOpenAfter,
  reducer,
  RESTING,
  SCRIPT,
  SEND_MS,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const TOTAL = CONVERSATIONS.length;

/** A narrow page shows the list until a conversation is opened. A wide one shows both. */
function listVisibilityOf(isReading: boolean) {
  if (isReading) {
    return 'hidden';
  }
  return 'flex';
}

function paneVisibilityOf(isReading: boolean) {
  if (isReading) {
    return 'flex';
  }
  return 'hidden';
}

export default function AiData03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const { selectedId } = state;
  const conversation = conversationOf(selectedId);
  const live = state.live[selectedId];
  const handled = handledCountOf(state);
  const next = nextOpenAfter(state, selectedId);
  const isStreaming = state.streamingId === selectedId && !shouldReduceMotion;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  const focusLater = useCallback(
    (selector: string) => {
      requestAnimationFrame(() => {
        const target = ref.current?.querySelector<HTMLElement>(selector);
        target?.focus();
      });
    },
    [ref]
  );

  /**
   * On a narrow page the list leaves when a conversation opens and takes the pressed row with it:
   * the focus then goes to the heading of the conversation. On a wide page the row keeps it.
   */
  const open = useCallback(
    (id: string) => {
      act({ type: 'opened', id });
      requestAnimationFrame(() => {
        const row = ref.current?.querySelector<HTMLElement>(
          `[data-row="${id}"]`
        );
        const isRowHidden = row?.offsetParent === null;
        if (isRowHidden) {
          focusLater('[data-pane-heading]');
        }
      });
    },
    [act, ref, focusLater]
  );

  function back() {
    act({ type: 'closed' });
    focusLater(`[data-row="${selectedId}"]`);
  }

  function focusWhatComesNext() {
    requestAnimationFrame(() => {
      const root = ref.current;
      const next = root?.querySelector<HTMLElement>('[data-next]');
      const reopen = root?.querySelector<HTMLElement>('[data-reopen]');
      const target = next ?? reopen;
      target?.focus();
    });
  }

  /** Send leaves with the draft once the reply is gone: a focus that sat on it goes to what can be done next. */
  function deliver(id: string) {
    const sendButton = ref.current?.querySelector('[data-send]');
    const hadFocus = sendButton === document.activeElement;
    act({ type: 'delivered', id });
    if (sendButton && hadFocus) {
      focusWhatComesNext();
    }
  }

  function send() {
    act({ type: 'sendPressed', id: selectedId });
    schedule(() => deliver(selectedId), SEND_MS);
  }

  function edit() {
    act({ type: 'editStarted', id: selectedId });
    requestAnimationFrame(() => {
      const field =
        ref.current?.querySelector<HTMLTextAreaElement>('[data-draft-field]');
      if (!field) {
        return;
      }
      const end = field.value.length;
      field.focus();
      field.setSelectionRange(end, end);
    });
  }

  function save() {
    act({ type: 'editSaved', id: selectedId });
    focusLater('[data-edit]');
  }

  function cancel() {
    act({ type: 'editCancelled', id: selectedId });
    focusLater('[data-edit]');
  }

  function reopen() {
    act({ type: 'reopened', id: selectedId });
    focusLater('[data-send]');
  }

  function openNext() {
    if (!next) {
      return;
    }
    act({ type: 'opened', id: next.id });
    focusLater('[data-pane-heading]');
  }

  /** A reply on its way belongs to the round it was sent in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-5 p-4 @3xl:gap-6 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='text-lg font-semibold text-balance'>Inbox</h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
                <span className='flex items-center gap-1.5'>
                  <MeshTile
                    seed={WRITER.name}
                    size='sm'
                    color={seriesColorOf(WRITER.series)}
                  />
                  Sorted and drafted by {WRITER.name}
                </span>
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={replay}
              label='Replay'
            />
            <p className='flex items-baseline gap-1.5'>
              <MotionNumber
                value={handled}
                className='text-2xl leading-8 font-semibold'
              />
              <span className='text-muted-foreground text-xs tabular-nums'>
                of {TOTAL} handled
              </span>
            </p>
          </header>

          <div className='flex gap-6'>
            <div
              className={cn(
                'w-full @3xl:flex @3xl:w-80 @3xl:shrink-0',
                listVisibilityOf(state.isReading)
              )}
            >
              <InboxList
                live={state.live}
                selectedId={selectedId}
                pressed={pressed}
                onOpen={open}
              />
            </div>
            <div
              className={cn(
                'min-w-0 flex-1 @3xl:sticky @3xl:top-8 @3xl:flex @3xl:self-start',
                paneVisibilityOf(state.isReading)
              )}
            >
              <ReadingPane
                key={selectedId}
                conversation={conversation}
                live={live}
                isStreaming={isStreaming}
                hasNext={next !== null}
                pressed={pressed}
                onBack={back}
                onSend={send}
                onEdit={edit}
                onType={(text) =>
                  act({ type: 'draftTyped', id: selectedId, text })
                }
                onSave={save}
                onCancel={cancel}
                onRegenerate={() =>
                  act({ type: 'regenerated', id: selectedId })
                }
                onReopen={reopen}
                onNext={openNext}
              />
            </div>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { memo } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import { CONVERSATIONS, TOPICS, type Conversation, type TopicId } from './data';
import { DrawnCheck } from './drawn-check';
import type { ConversationLive } from './session';

const ROW =
  'focus-visible:ring-ring/25 flex w-full cursor-pointer items-start gap-2.5 rounded-lg px-2.5 py-2 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px]';

function rowToneOf(isSelected: boolean) {
  if (isSelected) {
    return 'bg-foreground/[0.07]';
  }
  return 'hover:bg-foreground/[0.04]';
}

function currentOf(isSelected: boolean): 'true' | undefined {
  if (isSelected) {
    return 'true';
  }
  return undefined;
}

/** A handled row steps back where it stands. It never leaves its place in the list. */
function dimOf(isHandled: boolean) {
  if (isHandled) {
    return 'opacity-55';
  }
  return 'opacity-100';
}

/** Only what is urgent wears a colour: the other topics are told apart by their name. */
function topicDotOf(topic: TopicId) {
  if (topic === 'urgent') {
    return 'bg-destructive';
  }
  return 'bg-foreground/25';
}

function conversationsWordOf(count: number) {
  if (count === 1) {
    return 'conversation';
  }
  return 'conversations';
}

type ConversationRowProps = {
  conversation: Conversation;
  live: ConversationLive;
  isSelected: boolean;
  isPressed: boolean;
  onOpen: (id: string) => void;
};

/** Memoised: a key typed in the draft of one conversation draws its own row again, not the nine others. */
const ConversationRow = memo(function ConversationRow({
  conversation,
  live,
  isSelected,
  isPressed,
  onOpen,
}: ConversationRowProps) {
  const isHandled = live.status === 'handled';

  return (
    <li className={cn('transition-opacity duration-300', dimOf(isHandled))}>
      <button
        type='button'
        data-row={conversation.id}
        aria-current={currentOf(isSelected)}
        onClick={() => onOpen(conversation.id)}
        className={cn(ROW, rowToneOf(isSelected), pressedQuietOf(isPressed))}
      >
        <Avatar seed={conversation.customer} className='mt-0.5 size-7' />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='flex items-center gap-2'>
            <span className='min-w-0 flex-1 truncate text-[13px] leading-5 font-medium'>
              {conversation.customer}
            </span>
            <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
              {conversation.receivedAgo}
            </span>
          </span>
          <span className='truncate text-[13px] leading-5'>
            {conversation.subject}
          </span>
          <span className='text-muted-foreground truncate text-xs'>
            {conversation.reason}
          </span>
        </span>
        <span className='flex size-[18px] shrink-0 items-center justify-center self-center'>
          {isHandled && <DrawnCheck />}
        </span>
        {isHandled && <span className='sr-only'>Handled</span>}
      </button>
    </li>
  );
});

const ARROW_STEP: Partial<Record<string, number>> = {
  ArrowDown: 1,
  ArrowUp: -1,
};

/** Up and Down walk the rows across the topics, as one list. */
function moveBetweenRows(event: React.KeyboardEvent<HTMLElement>) {
  const step = ARROW_STEP[event.key];
  if (step === undefined) {
    return;
  }
  const rows = event.currentTarget.querySelectorAll<HTMLElement>('[data-row]');
  const buttons = Array.from(rows);
  const index = buttons.findIndex((row) => row === document.activeElement);
  if (index === -1) {
    return;
  }
  const target = buttons[index + step];
  if (!target) {
    return;
  }
  event.preventDefault();
  target.focus();
}

export type InboxListProps = {
  live: Record<string, ConversationLive>;
  selectedId: string;
  pressed: string | null;
  onOpen: (id: string) => void;
};

export function InboxList({
  live,
  selectedId,
  pressed,
  onOpen,
}: InboxListProps) {
  return (
    <nav
      aria-label='Conversations'
      onKeyDown={moveBetweenRows}
      className='flex w-full flex-col gap-4'
    >
      {TOPICS.map((topic) => {
        const conversations = CONVERSATIONS.filter(
          (conversation) => conversation.topic === topic.id
        );
        const count = conversations.length;
        return (
          <section key={topic.id} className='flex flex-col gap-0.5'>
            <h2 className='text-muted-foreground flex h-6 items-center gap-2 px-2.5 text-xs font-medium'>
              <span
                aria-hidden='true'
                className={cn(
                  'size-1.5 shrink-0 rounded-full',
                  topicDotOf(topic.id)
                )}
              />
              {topic.label}
              <span className='tabular-nums'>
                {count}
                <span className='sr-only'> {conversationsWordOf(count)}</span>
              </span>
            </h2>
            <ul className='flex flex-col gap-px'>
              {conversations.map((conversation) => (
                <ConversationRow
                  key={conversation.id}
                  conversation={conversation}
                  live={live[conversation.id]}
                  isSelected={conversation.id === selectedId}
                  isPressed={pressed === `row-${conversation.id}`}
                  onOpen={onOpen}
                />
              ))}
            </ul>
          </section>
        );
      })}
    </nav>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import {
  ArrowLeftIcon,
  ArrowRightIcon,
  BookOpenIcon,
  CheckIcon,
  RefreshCwIcon,
  SendIcon,
  UndoIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import {
  articlesOf,
  ME,
  topicLabelOf,
  WRITER,
  type Conversation,
  type TopicId,
} from './data';
import { draftOf, type ConversationLive, type SendStatus } from './session';
import { StreamedWords } from './streamed-words';

/** How long one word of a rewritten draft takes to follow the one before it. */
const WORD_MS = 40;

const SEND_STATE: Record<SendStatus, MorphState> = {
  open: 'idle',
  sending: 'busy',
  handled: 'done',
};

const SEND_LABELS: Record<MorphState, string> = {
  idle: 'Send',
  busy: 'Sending',
  done: 'Sent',
};

function topicVariantOf(topic: TopicId) {
  if (topic === 'urgent') {
    return 'destructive';
  }
  return 'secondary';
}

/** Draft 2 of 2 while the words are the agent's, and whose they are once a person changed them. */
function versionLineOf(conversation: Conversation, live: ConversationLive) {
  if (live.edited !== null) {
    return 'Edited by you';
  }
  return `Draft ${live.variant + 1} of ${conversation.drafts.length}`;
}

type DraftCardProps = {
  conversation: Conversation;
  live: ConversationLive;
  isStreaming: boolean;
  pressed: string | null;
  onSend: () => void;
  onEdit: () => void;
  onType: (text: string) => void;
  onSave: () => void;
  onCancel: () => void;
  onRegenerate: () => void;
};

function DraftCard({
  conversation,
  live,
  isStreaming,
  pressed,
  onSend,
  onEdit,
  onType,
  onSave,
  onCancel,
  onRegenerate,
}: DraftCardProps) {
  const fieldId = useId();
  const isEditing = live.editing !== null;
  const isSending = live.status === 'sending';
  const editingText = live.editing ?? '';
  const isEmpty = editingText.trim() === '';
  const versionLine = versionLineOf(conversation, live);
  const sources = articlesOf(conversation);

  return (
    <section
      aria-label='Draft reply'
      className='bg-foreground/[0.04] flex flex-col gap-3 rounded-xl p-3.5'
    >
      <header className='flex items-center gap-2'>
        <MeshTile seed={WRITER.name} color={seriesColorOf(WRITER.series)} />
        <h3 className='min-w-0 flex-1 truncate text-[13px] font-medium'>
          Draft by {WRITER.name}
        </h3>
        <Swap
          swapKey={versionLine}
          className='text-muted-foreground text-xs tabular-nums'
        >
          {versionLine}
        </Swap>
      </header>
      {!isEditing && (
        <p
          key={live.rewrites}
          className='text-[13px] leading-relaxed whitespace-pre-line'
        >
          <StreamedWords
            text={draftOf(conversation, live)}
            isStreaming={isStreaming}
            wordMs={WORD_MS}
          />
        </p>
      )}
      {isEditing && (
        <div className='flex flex-col gap-1.5'>
          <label htmlFor={fieldId} className='sr-only'>
            Reply to {conversation.customer}
          </label>
          <Textarea
            id={fieldId}
            data-draft-field
            value={editingText}
            onChange={(event) => onType(event.target.value)}
          />
        </div>
      )}
      <ul aria-label='Sources' className='flex flex-wrap gap-1.5'>
        {sources.map((article) => (
          <li
            key={article.id}
            className='bg-card dark:bg-foreground/[0.06] flex h-6 max-w-full items-center gap-1.5 rounded-full ps-2 pe-2.5 text-xs'
          >
            <BookOpenIcon className='text-muted-foreground size-3.5 shrink-0' />
            <span className='min-w-0 truncate'>{article.title}</span>
          </li>
        ))}
      </ul>
      {!isEditing && (
        <div className='flex flex-wrap items-center gap-2'>
          <MorphButton
            type='button'
            size='sm'
            data-send
            state={SEND_STATE[live.status]}
            labels={SEND_LABELS}
            idleIcon={<SendIcon />}
            onClick={onSend}
            className={pressedSolidOf(pressed === 'send')}
          />
          <Button
            type='button'
            size='sm'
            variant='outline'
            data-edit
            disabled={isSending}
            onClick={onEdit}
            className={pressedQuietOf(pressed === 'edit')}
          >
            Edit
          </Button>
          <Button
            type='button'
            size='sm'
            variant='ghost'
            disabled={isSending}
            onClick={onRegenerate}
            className={cn(
              'text-muted-foreground',
              pressedQuietOf(pressed === 'regenerate')
            )}
          >
            <RefreshCwIcon />
            Regenerate
          </Button>
        </div>
      )}
      {isEditing && (
        <div className='flex flex-wrap items-center gap-2'>
          <Button
            type='button'
            size='sm'
            disabled={isEmpty}
            focusableWhenDisabled
            onClick={onSave}
            className={pressedSolidOf(pressed === 'save')}
          >
            Save draft
          </Button>
          <Button type='button' size='sm' variant='ghost' onClick={onCancel}>
            Cancel
          </Button>
        </div>
      )}
    </section>
  );
}

type HandledProps = {
  hasNext: boolean;
  onReopen: () => void;
  onNext: () => void;
};

function Handled({ hasNext, onReopen, onNext }: HandledProps) {
  return (
    <div className='flex flex-wrap items-center gap-2'>
      <p className='text-muted-foreground flex min-w-0 flex-1 items-center gap-1.5 text-xs'>
        <CheckIcon className='text-success-foreground size-3.5 shrink-0' />
        Handled. Your reply is in the thread
      </p>
      <Button
        type='button'
        variant='ghost'
        size='sm'
        data-reopen
        onClick={onReopen}
        className='text-muted-foreground'
      >
        <UndoIcon />
        Reopen
      </Button>
      {hasNext && (
        <Button type='button' size='sm' data-next onClick={onNext}>
          Next conversation
          <ArrowRightIcon />
        </Button>
      )}
    </div>
  );
}

export type ReadingPaneProps = DraftCardProps &
  HandledProps & {
    onBack: () => void;
  };

/** The conversation on one side of the thread, the reply on the other, and under them what is left to do. */
export function ReadingPane({
  conversation,
  live,
  hasNext,
  pressed,
  onBack,
  onReopen,
  onNext,
  ...draft
}: ReadingPaneProps) {
  const headingId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const isHandled = live.status === 'handled';

  return (
    <section
      aria-labelledby={headingId}
      className='flex min-w-0 flex-1 flex-col gap-4'
    >
      <header className='flex items-start gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          data-back
          aria-label='Back to the conversations'
          onClick={onBack}
          className={cn(
            'text-muted-foreground -ms-1.5 shrink-0 @3xl:hidden',
            pressedQuietOf(pressed === 'back')
          )}
        >
          <ArrowLeftIcon />
        </Button>
        <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <h2
            id={headingId}
            data-pane-heading
            tabIndex={-1}
            className='focus-visible:ring-ring/25 rounded-sm text-sm leading-7 font-medium text-balance outline-none focus-visible:ring-[3px]'
          >
            {conversation.subject}
          </h2>
          <p className='text-muted-foreground flex min-w-0 items-center gap-1.5 text-xs'>
            <CompanyMark seed={conversation.company} size='sm' />
            <span className='truncate'>
              {conversation.customer}, {conversation.company}
            </span>
          </p>
        </div>
        <Badge variant={topicVariantOf(conversation.topic)} className='mt-1'>
          {topicLabelOf(conversation.topic)}
        </Badge>
      </header>

      <div className='flex flex-col'>
        <div className='flex items-end gap-2 pb-3'>
          <Avatar seed={conversation.customer} className='size-7' />
          <div className='flex max-w-[85%] flex-col gap-1'>
            <p className='bg-foreground/[0.06] rounded-2xl rounded-es-md px-3.5 py-2 text-[13px] leading-relaxed'>
              {conversation.message}
            </p>
            <p className='text-muted-foreground ps-1 text-xs tabular-nums'>
              {conversation.receivedAgo} ago
            </p>
          </div>
        </div>
        <AnimatePresence initial={false}>
          {live.sent !== null && (
            <motion.div
              key='sent'
              className='-mx-1 overflow-hidden px-1'
              {...rowPresence}
            >
              <div className='flex items-end justify-end gap-2 pb-3'>
                <p className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] max-w-[85%] rounded-2xl rounded-ee-md px-3.5 py-2 text-[13px] leading-relaxed whitespace-pre-line shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
                  {live.sent}
                </p>
                <Avatar seed={ME.name} className='size-7' />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <AnimatedSize>
        {!isHandled && (
          <DraftCard
            conversation={conversation}
            live={live}
            pressed={pressed}
            {...draft}
          />
        )}
        {isHandled && (
          <Handled hasNext={hasNext} onReopen={onReopen} onNext={onNext} />
        )}
      </AnimatedSize>
    </section>
  );
}

import { Fragment } from 'react';

const ARRIVING =
  'opacity-100 transition-opacity duration-300 ease-(--ease-out-strong) starting:opacity-0';

function inkOf(isStreaming: boolean) {
  if (isStreaming) {
    return ARRIVING;
  }
  return undefined;
}

/** Each word waits its turn through its own delay, so nothing ticks in script while a text arrives. */
function delayOf(isStreaming: boolean, index: number, wordMs: number) {
  if (!isStreaming) {
    return undefined;
  }
  const delay = index * wordMs;
  return { transitionDelay: `${delay}ms` };
}

function leadingSpaceOf(index: number) {
  if (index === 0) {
    return '';
  }
  return ' ';
}

type StreamedWordsProps = {
  text: string;
  /** True for a text that has just been written: its words fade in one after the other. */
  isStreaming: boolean;
  wordMs: number;
};

/**
 * Every word is in the page from the start, so the paragraph has its final height at once and
 * a screen reader gets the whole text. Only the ink arrives word by word.
 */
export function StreamedWords({
  text,
  isStreaming,
  wordMs,
}: StreamedWordsProps) {
  const words = text.split(' ');

  return (
    <>
      {words.map((word, index) => (
        <Fragment key={index}>
          {leadingSpaceOf(index)}
          <span
            style={delayOf(isStreaming, index, wordMs)}
            className={inkOf(isStreaming)}
          >
            {word}
          </span>
        </Fragment>
      ))}
    </>
  );
}

'use client';

import { motion, type Variants } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const CHECK_PATH = 'M2.6 6.4 4.9 8.7 9.5 3.6';

const DRAW = { duration: 0.32, ease: EASE_OUT_STRONG, delay: 0.1 };

const STROKE: Variants = {
  waiting: { pathLength: 0 },
  drawn: { pathLength: 1, transition: DRAW },
};

const STROKE_STILL: Variants = {
  waiting: { pathLength: 1 },
  drawn: { pathLength: 1 },
};

function strokeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STROKE_STILL;
  }
  return STROKE;
}

const ONCE = { once: true };

/**
 * The check draws itself the first time it is on screen, not when it mounts: on a narrow page the
 * list is hidden while a reply is sent, and the stroke waits for the list to come back.
 */
export function DrawnCheck({ className }: { className?: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.span
      initial='waiting'
      whileInView='drawn'
      viewport={ONCE}
      className={cn(
        'chip-3d inline-flex size-[18px] shrink-0 items-center justify-center rounded-full [--chip:var(--success)]',
        className
      )}
    >
      <svg aria-hidden='true' viewBox='0 0 12 12' className='size-3'>
        <motion.path
          d={CHECK_PATH}
          fill='none'
          stroke='currentColor'
          strokeWidth='1.9'
          strokeLinecap='round'
          strokeLinejoin='round'
          variants={strokeOf(shouldReduceMotion)}
        />
      </svg>
    </motion.span>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { conversationOf, CONVERSATIONS, type Conversation } from './data';

export type SendStatus = 'open' | 'sending' | 'handled';

export type ConversationLive = {
  status: SendStatus;
  /** Which of the agent's drafts shows. */
  variant: number;
  /** The draft as a person saved it, once they changed it. */
  edited: string | null;
  /** What the editing field holds while the draft is being changed. */
  editing: string | null;
  /** Counts the rewrites, so a rewritten draft arrives as a new text. */
  rewrites: number;
  /** The reply that was sent. */
  sent: string | null;
};

export type InboxState = {
  selectedId: string;
  /** A narrow page shows the list or the conversation, never both. */
  isReading: boolean;
  live: Record<string, ConversationLive>;
  /** The conversation whose draft is arriving word by word. */
  streamingId: string | null;
  spoken: string;
};

export type InboxAction =
  | { type: 'opened'; id: string }
  | { type: 'closed' }
  | { type: 'regenerated'; id: string }
  | { type: 'editStarted'; id: string }
  | { type: 'draftTyped'; id: string; text: string }
  | { type: 'editSaved'; id: string }
  | { type: 'editCancelled'; id: string }
  | { type: 'sendPressed'; id: string }
  | { type: 'delivered'; id: string }
  | { type: 'reopened'; id: string };

type Step = SessionStep<InboxState, InboxAction>;

const FRESH: ConversationLive = {
  status: 'open',
  variant: 0,
  edited: null,
  editing: null,
  rewrites: 0,
  sent: null,
};

function initialLiveOf() {
  const live: Record<string, ConversationLive> = {};
  for (const conversation of CONVERSATIONS) {
    live[conversation.id] = FRESH;
  }
  return live;
}

const [FIRST, SECOND] = CONVERSATIONS;

export const INITIAL: InboxState = {
  selectedId: FIRST.id,
  isReading: false,
  live: initialLiveOf(),
  streamingId: null,
  spoken: '',
};

/** The reply as it would be sent: what a person saved, or the draft of the agent. */
export function draftOf(conversation: Conversation, live: ConversationLive) {
  return live.edited ?? conversation.drafts[live.variant];
}

export function handledCountOf(state: InboxState) {
  const handled = CONVERSATIONS.filter(
    (conversation) => state.live[conversation.id].status === 'handled'
  );
  return handled.length;
}

/** The next conversation down the list that still waits for a reply, starting again from the top. */
export function nextOpenAfter(state: InboxState, id: string) {
  const index = CONVERSATIONS.findIndex((candidate) => candidate.id === id);
  const after = CONVERSATIONS.slice(index + 1);
  const before = CONVERSATIONS.slice(0, index);
  const others = [...after, ...before];
  const next = others.find(
    (candidate) => state.live[candidate.id].status === 'open'
  );
  return next ?? null;
}

function patched(
  state: InboxState,
  id: string,
  patch: Partial<ConversationLive>
): InboxState {
  const live = { ...state.live[id], ...patch };
  return { ...state, live: { ...state.live, [id]: live } };
}

function isKnown(state: InboxState, id: string) {
  return state.live[id] !== undefined;
}

function opened(state: InboxState, id: string): InboxState {
  if (!isKnown(state, id)) {
    return state;
  }
  const conversation = conversationOf(id);
  const spoken = `${conversation.customer}: ${conversation.subject}`;
  return {
    ...state,
    selectedId: id,
    isReading: true,
    streamingId: null,
    spoken,
  };
}

/** A draft can be rewritten or sent while it is open and nobody is changing it. */
function isReady(live: ConversationLive | undefined) {
  if (!live) {
    return false;
  }
  const isOpen = live.status === 'open';
  const isBeingEdited = live.editing !== null;
  return isOpen && !isBeingEdited;
}

function regenerated(state: InboxState, id: string): InboxState {
  const live = state.live[id];
  if (!isReady(live)) {
    return state;
  }
  const conversation = conversationOf(id);
  const variant = (live.variant + 1) % conversation.drafts.length;
  const rewrites = live.rewrites + 1;
  const next = patched(state, id, { variant, edited: null, rewrites });
  return { ...next, streamingId: id, spoken: 'Draft rewritten' };
}

function editStarted(state: InboxState, id: string): InboxState {
  const live = state.live[id];
  if (!isReady(live)) {
    return state;
  }
  const editing = draftOf(conversationOf(id), live);
  const next = patched(state, id, { editing });
  return { ...next, streamingId: null };
}

function isEditing(state: InboxState, id: string) {
  const live = state.live[id];
  return live !== undefined && live.editing !== null;
}

function draftTyped(state: InboxState, id: string, text: string): InboxState {
  if (!isEditing(state, id)) {
    return state;
  }
  return patched(state, id, { editing: text });
}

/** An empty reply cannot be saved: the button that saves it is off while the field is empty. */
function editSaved(state: InboxState, id: string): InboxState {
  const editing = state.live[id]?.editing ?? null;
  if (editing === null) {
    return state;
  }
  const text = editing.trim();
  if (text === '') {
    return state;
  }
  const next = patched(state, id, { edited: text, editing: null });
  return { ...next, spoken: 'Draft saved' };
}

function editCancelled(state: InboxState, id: string): InboxState {
  if (!isEditing(state, id)) {
    return state;
  }
  return patched(state, id, { editing: null });
}

function sendPressed(state: InboxState, id: string): InboxState {
  if (!isReady(state.live[id])) {
    return state;
  }
  const next = patched(state, id, { status: 'sending' });
  return { ...next, streamingId: null };
}

function delivered(state: InboxState, id: string): InboxState {
  const live = state.live[id];
  if (live?.status !== 'sending') {
    return state;
  }
  const conversation = conversationOf(id);
  const sent = draftOf(conversation, live);
  const next = patched(state, id, { status: 'handled', sent });
  const handled = handledCountOf(next);
  const total = CONVERSATIONS.length;
  const spoken = `Reply sent to ${conversation.customer}. ${handled} of ${total} handled`;
  return { ...next, spoken };
}

function reopened(state: InboxState, id: string): InboxState {
  if (state.live[id]?.status !== 'handled') {
    return state;
  }
  const next = patched(state, id, { status: 'open', sent: null });
  return { ...next, spoken: 'Conversation reopened' };
}

export function reducer(state: InboxState, action: InboxAction): InboxState {
  switch (action.type) {
    case 'opened':
      return opened(state, action.id);
    case 'closed':
      return { ...state, isReading: false };
    case 'regenerated':
      return regenerated(state, action.id);
    case 'editStarted':
      return editStarted(state, action.id);
    case 'draftTyped':
      return draftTyped(state, action.id, action.text);
    case 'editSaved':
      return editSaved(state, action.id);
    case 'editCancelled':
      return editCancelled(state, action.id);
    case 'sendPressed':
      return sendPressed(state, action.id);
    case 'delivered':
      return delivered(state, action.id);
    case 'reopened':
      return reopened(state, action.id);
  }
}

/** How long a reply takes to leave. */
export const SEND_MS = 900;

const KEY_MS = 40;

/** What the demonstration adds to the second draft before it saves it. */
const ADDED_SENTENCE = ' Thank you for flagging it so quickly.';

const [SECOND_DRAFT] = SECOND.drafts;

function typingSteps(startAfter: number): Step[] {
  const prefixes = prefixesOf(ADDED_SENTENCE);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: {
      type: 'draftTyped',
      id: SECOND.id,
      text: `${SECOND_DRAFT}${typed}`,
    },
  }));
}

/**
 * The inbox is already sorted and drafted, so a person does everything from here and every step
 * is the demonstration's, except the reply that leaves on its own once Send is pressed. The first
 * draft is rewritten and sent, then the second one is edited and saved.
 */
export const SCRIPT: Step[] = [
  {
    after: 1500,
    by: 'demo',
    press: `row-${FIRST.id}`,
    action: { type: 'opened', id: FIRST.id },
  },
  {
    after: 1900,
    by: 'demo',
    press: 'regenerate',
    action: { type: 'regenerated', id: FIRST.id },
  },
  {
    after: 3400,
    by: 'demo',
    press: 'send',
    action: { type: 'sendPressed', id: FIRST.id },
  },
  { after: SEND_MS, action: { type: 'delivered', id: FIRST.id } },
  { after: 1700, by: 'demo', press: 'back', action: { type: 'closed' } },
  {
    after: 1400,
    by: 'demo',
    press: `row-${SECOND.id}`,
    action: { type: 'opened', id: SECOND.id },
  },
  {
    after: 1700,
    by: 'demo',
    press: 'edit',
    action: { type: 'editStarted', id: SECOND.id },
  },
  ...typingSteps(900),
  {
    after: 800,
    by: 'demo',
    press: 'save',
    action: { type: 'editSaved', id: SECOND.id },
  },
];

function endOf(script: Step[]) {
  let state = INITIAL;
  for (const step of script) {
    state = reducer(state, step.action);
  }
  return state;
}

/**
 * Under reduced motion the inbox rests where the script ends: the first conversation is handled in
 * its place, and the second one is open with the draft a person just changed.
 */
export const RESTING: InboxState = { ...endOf(SCRIPT), spoken: '' };

